inline constexpr std::size_t RL_QUANT_U16_COUNT = 4;
inline constexpr std::size_t RL_QUANT_I16_COUNT = 231;
// Byte layout of the observation inside a packed row: bits at 0, then the u8 group, the u16 group and the i16 group.  The bit of the slot with column c is (byte[c / 8] >> (c % 8)) & 1 (LSB first);
// a u8 slot is byte[RL_QUANT_U8_OFFSET + column]; a u16 or i16 slot is a little-endian 16-bit word at RL_QUANT_U16_OFFSET + 2 * column or RL_QUANT_I16_OFFSET + 2 * column.
inline constexpr std::size_t RL_QUANT_BIT_BYTES = 23;
inline constexpr std::size_t RL_QUANT_U8_OFFSET = 23;
inline constexpr std::size_t RL_QUANT_U16_OFFSET = 121;
inline constexpr std::size_t RL_QUANT_I16_OFFSET = 129;
inline constexpr std::size_t RL_QUANT_OBS_BYTES = 591;
// The whole packed shard row: the observation plus action, mask, chosen target, flags, reward, damage_to_end, t and t_decided.
inline constexpr std::size_t RL_SHARD_ROW_BYTES = 615;
static_assert(RL_QUANT_BIT_COUNT + RL_QUANT_U8_COUNT + RL_QUANT_U16_COUNT + RL_QUANT_I16_COUNT == RL_OBS_DIM, "the quant table classes every observation slot exactly once");
static_assert(RL_QUANT_BIT_BYTES == (RL_QUANT_BIT_COUNT + 7) / 8 && RL_QUANT_U8_OFFSET == RL_QUANT_BIT_BYTES, "bit group bytes");
static_assert(RL_QUANT_U16_OFFSET == RL_QUANT_U8_OFFSET + RL_QUANT_U8_COUNT && RL_QUANT_I16_OFFSET == RL_QUANT_U16_OFFSET + 2 * RL_QUANT_U16_COUNT, "group offsets");
static_assert(RL_QUANT_OBS_BYTES == RL_QUANT_I16_OFFSET + 2 * RL_QUANT_I16_COUNT, "observation bytes");

enum class rl_quant_class { bit, u8_lattice, u16_lattice, i16_fixed };

// One row per observation slot, in slot order.  `column` is the position inside the slot's class group.  `div` is the lattice divisor (the value of code k is float32(double(k) / div), the
// tables below); a fixed slot stores q = rint((double(v) - lo) * inv_step) minus 32768 and decodes float32(q) * float32(step) + float32(lo).  Fields a class does not use read 0.0.
struct rl_quant_slot
{
  rl_quant_class cls;
  std::size_t    column;
  double         div;
  double         lo;
  double         hi;
  double         step;
  double         inv_step;
};

